<?php
require __DIR__.'/app/bootstrap.php';require_login();require __DIR__.'/app/layout.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$applicantId=filter_input(INPUT_GET,'applicant_id',FILTER_VALIDATE_INT)?:0;$editing=$id>0;$errors=[];$d=['applicant_id'=>$applicantId,'card_number'=>'','issue_date'=>'','expiry_date'=>'','status'=>'Pending','notes'=>''];
if($editing){$st=$pdo->prepare('SELECT * FROM id_cards WHERE id=?');$st->execute([$id]);$row=$st->fetch();if(!$row){flash('error','Card record not found.');redirect('cards.php');}$d=array_merge($d,$row);}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($d as $k=>$v)if(isset($_POST[$k]))$d[$k]=trim((string)$_POST[$k]);$d['applicant_id']=(int)$d['applicant_id'];
$st=$pdo->prepare('SELECT id FROM applicants WHERE id=?');$st->execute([$d['applicant_id']]);if(!$st->fetch())$errors[]='Select a valid applicant.';
if($d['card_number']===''||!preg_match('/^[A-Za-z0-9-]{4,40}$/',$d['card_number']))$errors[]='Card number is required (4–40 letters, numbers or hyphens).';
if(!in_array($d['status'],['Pending','Printed','Issued','Lost','Expired','Cancelled'],true))$errors[]='Select a valid card status.';
foreach(['issue_date','expiry_date'] as $k)if($d[$k]!==''&&(!DateTime::createFromFormat('!Y-m-d',$d[$k])||DateTime::createFromFormat('!Y-m-d',$d[$k])->format('Y-m-d')!==$d[$k]))$errors[]='Enter a valid '.$k.'.';
if($d['issue_date']!==''&&$d['expiry_date']!==''&&$d['expiry_date']<$d['issue_date'])$errors[]='Expiry date cannot be earlier than issue date.';
if($d['status']==='Issued'&&$d['issue_date']==='')$errors[]='An issue date is required when card status is Issued.';
if(!$errors){try{if($editing){$st=$pdo->prepare('UPDATE id_cards SET applicant_id=?,card_number=?,issue_date=?,expiry_date=?,status=?,notes=?,updated_at=NOW() WHERE id=?');$st->execute([$d['applicant_id'],$d['card_number'],$d['issue_date']?:null,$d['expiry_date']?:null,$d['status'],$d['notes']?:null,$id]);$cardId=$id;$action='UPDATE_CARD';}else{$st=$pdo->prepare('INSERT INTO id_cards (applicant_id,card_number,issue_date,expiry_date,status,notes) VALUES (?,?,?,?,?,?)');$st->execute([$d['applicant_id'],$d['card_number'],$d['issue_date']?:null,$d['expiry_date']?:null,$d['status'],$d['notes']?:null]);$cardId=(int)$pdo->lastInsertId();$action='CREATE_CARD';}log_activity($pdo,$action,(int)$d['applicant_id'],'Card '.$d['card_number'].' status '.$d['status']);flash('success','ID card record saved successfully.');redirect('cards.php');}catch(PDOException $e){if($e->getCode()==='23000')$errors[]='That card number is already in use.';else{$errors[]='Unable to save card details.';error_log($e->getMessage());}}}}
$people=$pdo->query("SELECT id,applicant_no,first_name,last_name FROM applicants ORDER BY last_name,first_name")->fetchAll();page_header($editing?'Edit ID card':'Record ID card'); ?>
<?php if($errors): ?><div class="alert error"><ul><?php foreach($errors as $er): ?><li><?=e($er)?></li><?php endforeach; ?></ul></div><?php endif; ?><form class="panel form-panel" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="section-title"><h2>Card issuance information</h2><p>Use fictional card numbers only.</p></div><div class="form-grid"><label class="span-2">Applicant *<select name="applicant_id" required><option value="">Choose applicant</option><?php foreach($people as $person): ?><option value="<?=(int)$person['id']?>" <?=(int)$d['applicant_id']===(int)$person['id']?'selected':''?>><?=e($person['applicant_no'].' — '.$person['first_name'].' '.$person['last_name'])?></option><?php endforeach; ?></select></label><label>Card number *<input name="card_number" maxlength="40" required value="<?=e($d['card_number'])?>" placeholder="e.g. DEMO-ID-0001"></label><label>Status *<select name="status"><?php foreach(['Pending','Printed','Issued','Lost','Expired','Cancelled'] as $v): ?><option <?=$d['status']===$v?'selected':''?>><?=e($v)?></option><?php endforeach; ?></select></label><label>Issue date<input type="date" name="issue_date" value="<?=e($d['issue_date'])?>"></label><label>Expiry date<input type="date" name="expiry_date" value="<?=e($d['expiry_date'])?>"></label><label class="span-2">Notes<textarea name="notes" rows="3" maxlength="500"><?=e($d['notes'])?></textarea></label></div><div class="form-actions"><a class="btn secondary" href="cards.php">Cancel</a><button class="btn primary" type="submit">Save card record</button></div></form><?php page_footer(); ?>
